joyMove(e){if(!this.joy.active||e.pointerId!==this.joy.id)return;const dx=e.clientX-this.joy.ox,dy=e.clientY-this.joy.oy,d=Math.hypot(dx,dy),k=Math.min(40,d)/(d||1);this.joy.x=dx*k/40;this.joy.y=dy*k/40;document.getElementById('joystick-thumb').style.transform='translate('+this.joy.x*40+'px,'+this.joy.y*40+'px)';if(this.player){this.player.moveTarget=null;this.player.order=false;this.player.move.set(this.joy.x,0,this.joy.y);this.cancelRecall();}}
playerMove(){const h=this.player;if(!h||h.dead)return;const k=this.keys||{},x=(k.d||k.arrowright?1:0)-(k.a||k.arrowleft?1:0),z=(k.s||k.arrowdown?1:0)-(k.w||k.arrowup?1:0);if(this.joy.active||x||z){h.moveTarget=null;h.move.set(this.joy.active?this.joy.x:x,0,this.joy.active?this.joy.y:z);h.order=false;h.target=null;if(h.move.lengthSq())this.cancelRecall();}else if(h.moveTarget){const d=dist(h.position,h.moveTarget);if(d<.8){h.moveTarget=null;h.move.set(0,0,0);}else h.move.copy(h.moveTarget).sub(h.position).setY(0).normalize();}else if(!h.order)h.move.set(0,0,0);}
attackOrder(){if(!this.started||this.paused||!this.player||this.player.dead)return;const h=this.player,t=this.nearest(h,18)||this.nextTower(h.team,h.lane)||this.core(enemy(h.team));if(!t){this.toast('附近没有可攻击目标');return;}h.target=t;h.order=true;h.move.set(0,0,0);h.moveTarget=null;this.cancelRecall();}
skill(i){if(this.started&&!this.paused&&this.player)this.player.skill(i);}
nearest(u,r){const a=[...this.heroes,...this.minions,...this.monsters].filter(x=>ok(x)&&(x.team==='neutral'||x.team!==u.team)&&Math.abs(x.position.z-u.position.z)<12).sort((x,y)=>dist(x.position,u.position)-dist(y.position,u.position));return a.length&&dist(a[0].position,u.position)<=r?a[0]:null;}
lowest(u,r){return this.heroes.filter(h=>ok(h)&&h.team===u.team&&h!==u&&dist(h.position,u.position)<r).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0]||null;}
nextTower(team,lane){const e=enemy(team),a=this.towers.filter(t=>ok(t)&&t.team===e&&!t.core&&t.lane===lane).sort((x,y)=>Math.abs(x.position.x-(team==='blue'?-50:50))-Math.abs(y.position.x-(team==='blue'?-50:50)));return a[0]||(this.coreOpen(e)?this.core(e):null);}
core(t){return this.towers.find(q=>q.core&&q.team===t&&!q.dead)||null;}
coreOpen(t){return LANES.some(l=>!this.towers.some(q=>!q.dead&&!q.core&&q.team===t&&q.lane===l.id));}
targets(){return [...this.heroes,...this.minions,...this.towers,...this.monsters];}
damage(t,n,s,type){if(ok(t)&&t.takeDamage)t.takeDamage(n,s,type);}
ai(h){h.move.set(0,0,0);if(h.hp/h.maxHp<.23){h.order=false;h.target=null;const x=h.team==='blue'?-52:52,z=LANES[h.lane].z;if(Math.hypot(x-h.position.x,z-h.position.z)>4)h.move.set(x-h.position.x,0,z-h.position.z).normalize();else{h.hp=Math.min(h.maxHp,h.hp+this.dt*h.maxHp*.12);h.mana=Math.min(h.maxMana,h.mana+this.dt*h.maxMana*.16);}return;}let t=this.nearest(h,8.5);if(!t){const a=this.minions.filter(m=>ok(m)&&m.team!==h.team&&m.lane===h.lane&&Math.abs(m.position.z-h.position.z)<5&&dist(m.position,h.position)<8).sort((x,y)=>dist(x.position,h.position)-dist(y.position,h.position));t=a[0]||null;}if(!t)t=this.nextTower(h.team,h.lane);h.target=t;h.order=!!t;if(t){const d=dist(h.position,t.position);if(d>h.range*.86)h.move.copy(t.position).sub(h.position).setY(0).normalize();else{if(h.cooldowns[0]<=0&&d<12)h.skill(0);if(h.cooldowns[1]<=0&&d<8)h.skill(1);if(h.cooldowns[2]<=0&&d<7&&(!t.hp||t.hp/t.maxHp<.58))h.skill(2);}}}
spawnWave(){if(!this.started)return;this.wave++;for(const l of LANES)for(const t of ['blue','red']){const d=t==='blue'?1:-1,x=t==='blue'?-52:52;for(let i=0;i<3;i++)this.minions.push(new Minion(this,t,l.id,'melee',x-d*i*1.25,l.z+(i-1)*.55));for(let i=0;i<2;i++)this.minions.push(new Minion(this,t,l.id,'ranged',x-d*(4+i*1.2),l.z+(i-.5)*.65));if(this.wave%3===0)this.minions.push(new Minion(this,t,l.id,'siege',x-d*7.2,l.z+.35));}if(this.minions.length>84)this.minions.splice(0,this.minions.length-84);}
heroDown(k,v){if(k.team==='blue')this.blueKills++;else this.redKills++;document.getElementById('blue-score').textContent=this.blueKills;document.getElementById('red-score').textContent=this.redKills;const f=document.getElementById('kill-feed'),e=document.createElement('div');e.className='kill-item';e.innerHTML='<b>'+k.name+'</b> 击败 <span class="enemy">'+v.name+'</span>';f.prepend(e);while(f.children.length>4)f.lastElementChild.remove();setTimeout(()=>e.remove(),5200);}
towerDown(t,s){this.burst(t.position,tc(t.team),5);this.toast(t.core?'敌方水晶已被摧毁':'防御塔被摧毁');if(t.core)this.end(s&&s.team==='blue');else if(s&&s.gain)s.gain(120,65);}
project(from,target,n,color,type,speed,source,spread){if(!target||!ok(target))return;const g=new THREE.Group();add(new THREE.SphereGeometry(.19,8,6),mat(color,{emissive:color,emissiveIntensity:1.1,roughness:.2}),g);const ring=add(new THREE.TorusGeometry(.29,.025,5,16),flat(color,.6),g);ring.rotation.x=Math.PI/2;g.position.copy(from);this.scene.add(g);this.projectiles.push({g,target,n,color,type,speed,life:3,source,spread:spread||0});}
burst(p,c,r){this.ring(p,c,r,.55);const q=rng(Math.floor((p.x+100)*10+(p.z+100)*21+performance.now()));for(let i=0;i<7;i++){const m=add(new THREE.SphereGeometry(.08+q()*.08,5,4),mat(c,{emissive:c,emissiveIntensity:.8}),this.scene,p.x,p.y+.7,p.z);this.particles.push({m,v:new THREE.Vector3((q()-.5)*5,1+q()*3,(q()-.5)*5),life:.38});}}
ring(p,c,r,life){const g=new THREE.Group();g.position.set(p.x,.09,p.z);const ring=add(new THREE.RingGeometry(Math.max(.1,r*.75),r,40),flat(c,.8),g);ring.rotation.x=-Math.PI/2;const fill=add(new THREE.CircleGeometry(r*.74,32),flat(c,.12),g,0,-.01,0);fill.rotation.x=-Math.PI/2;this.scene.add(g);this.effects.push({g,life,max:life,ring,fill});}
hit(p,c){this.ring(p,c,.7,.28);}
